#!/usr/bin/env python3
"""Writes tools/earnings/tracker_doc.md: the full text of the project doc
'claude/TNM - World Talent Earnings Tracker.md' (and ledger_summary.md for the
"Talent earnings" section of the World Finance Ledger). Run after build.py."""
import json,os
HERE=os.path.dirname(os.path.abspath(__file__)); ROOT=os.path.join(HERE,'..','..')
d=json.loads(open(os.path.join(ROOT,'data','earnings.js')).read().split('const EARNINGS = ',1)[1].rstrip().rstrip(';'))
board,shows=open(os.path.join(HERE,'earnings.md')).read().split('\nSHOWS\n')
tot=sum(x['earned'] for x in d['people']); due=sum(x['due'] for x in d['people'])
status=f"**Month:** {d['month']} · **World date:** {d['world']} · **Last rebuilt:** {d['updated']}\n**Paid out so far:** ${tot:,.0f} · **Japan tour fees still due:** ${due:,.0f} · **July projected:** ${tot+due:,.0f} · **People:** {len(d['people'])}\n"
TPL="# TNM — World Talent Earnings Tracker\n\nRunning record of what every wrestler and manager has been paid this month, across all nine promotions. Started 2026-11-11 (Sean). **Rebuilt every time the world clock moves** and after every show is logged. The same tracker is on the website: World → Talent Earnings (shovan123-lang.github.io/TNMWorld/#earnings), with a top-10 on each promotion's Finance tab and a top-5 on the front page.\n\n{STATUS}\n\n## How it's counted\n- **WWF and WCW (monthly salary):** salary accrues day by day through the world date (monthly rate × days ÷ 31). Tom Zenk's starts 7/11. Rates from `claude/TNM - World Talent Pay Scales (All Promotions).md`.\n- **USWA, CMLL, ASW, Tri-State, Power Pro (per appearance):** base rate × the show's multiplier, plus the main-event and semi-main gate cuts split evenly, for every show that has run (including Tri-State 7/19 and Power Pro 7/28, which have already run ahead of the world date). Local enhancement talent not on a scale (Johnny Rich, Jan Vang, Jody Burt, Jos LeDuc, Kerry Brown) get $15 a TV appearance.\n- **AJPW and NJPW (per tour):** the full tour fee shows as **due** until the last night (AJPW 7/27, NJPW 7/30), then moves to paid. Part-timers will be prorated when the tour closes. **Exception: Toshiaki Kawada** (leaving after Okayama 7/15) is paid per appearance instead, $1,000 a night (his $14,000 fee ÷ 14 nights), counted as each night runs (Sean, 2026-11-11). 5 nights so far = $5,000; Okayama makes it $6,000.\n- **Bonuses:** added on the night. So far: WrestleFest '91 main-event bonus, $25,678.50 each to Hogan and Slaughter. The Bash main-event bonus goes in once the Bash is logged.\n- **Not included:** announcers; Kevin Sullivan (worked three WCW dates before quitting 7/8, isn't on the pay scale).\n- The same wrestler is combined across promotions (e.g. Sting in WCW and NJPW, Owen Hart as the Blue Blazer, IRS as Mike Rotunda, Eddie Guerrero and Santo in USWA and CMLL).\n\n## Show-by-show check against the ledger\nItemized totals match the ledger's payroll for 10 of 15 shows. Where the itemized total is lower, the ledger figure also counted announcers or staff, or (CMLL 7/6 and 7/8) one worker the results don't name. The ledger figures stand; this tracker counts only the people named below.\n\n"
open(os.path.join(HERE,'tracker_doc.md'),'w').write(TPL.replace('{STATUS}',status)+shows+"\n## Leaderboard (ranked by paid so far)\n\n"+board)
PN={"wcw":"WCW","wwf":"WWF","uswa":"USWA","pp":"Power Pro","ajpw":"AJPW","njpw":"NJPW","cmll":"CMLL","asw":"ASW","twa":"TWA"}
m=lambda v:"${:,.0f}".format(v)
L=[f"**{d['month']}, world date {d['world'][5:7].lstrip('0')}/{d['world'][8:].lstrip('0')} (rebuilt {d['updated']}):** paid out so far {m(tot)} · Japan tour fees still due {m(due)} · July projected {m(tot+due)} · {len(d['people'])} people.","",
 "| # | Name | Promotions | Paid so far | Tour fees due | July projected |","|---|---|---|---|---|---|"]
for i,x in enumerate(d['people'][:15],1):
  b=f" (incl. {m(x['bonus'])} bonus)" if x['bonus'] else ""
  L.append(f"| {i} | {x['name']} | {', '.join(PN[k] for k in x['promos'])} | {m(x['earned'])}{b} | {m(x['due']) if x['due'] else '—'} | {m(x['proj'])} |")
open(os.path.join(HERE,'ledger_summary.md'),'w').write("\n".join(L)+"\n")
print("wrote tracker_doc.md and ledger_summary.md")
